def check_case(b, case_type):
    target = (2**(b+1) - 1)

    if case_type == 1:
        # Case 1: 3^q + 2 * 3^(b-q) = 2^(b+1)-1
        for q in range(b + 1):
            lhs = (3**q) + 2 * (3**(b - q))
            if lhs == target:
                return True
        return False

    elif case_type == 2:
        # Case 2: 2 * 3^q + 3^(b-q) = 2^(b+1)-1
        for q in range(b + 1):
            lhs = 2 * (3**q) + (3**(b - q))
            if lhs == target:
                return True
        return False

# Test b from 1 to 12
print("--- Case 1 Results ---")
case1_solutions = []
for b in range(1, 13):
    if check_case(b, 1):
        case1_solutions.append(b)
print(f"b values found for Case 1 (b <= 12): {case1_solutions}")

print("\n--- Case 2 Results ---")
case2_solutions = []
for b in range(1, 13):
    if check_case(b, 2):
        case2_solutions.append(b)
print(f"b values found for Case 2 (b <= 12): {case2_solutions}")
